export const MESSAGE_POOLS={mild:['A tiny reminder: your notes are waiting.','That tab can wait. Your study session is happening now.','Back to the thing that helps future-you.'],angry:['WHY ARE YOU OPENING ANOTHER TAB?','YOUR NOTES ARE STILL SITTING THERE.','THIS IS NOT HOW THE EXAM PASSES ITSELF.','BACK TO WORK.','INTERESTING STRATEGY. STUDYING WOULD ALSO BE AN OPTION.'],nuclear:['THE TAB GREMLINS WILL NOT DEFEAT YOUR STUDY PLAN.','BEHOLD: ANOTHER DISTRACTION. A BOLD, UNNECESSARY CHOICE.','YOUR FUTURE SELF HAS FILED A FORMAL COMPLAINT.','THE EXAM IS PACING. IT HAS QUESTIONS.','ABORT SIDE QUEST. RESUME MAIN QUEST: LEARNING.']};
export function chooseMessage(level='angry',random=Math.random){const pool=MESSAGE_POOLS[level]??MESSAGE_POOLS.angry;return pool[Math.floor(random()*pool.length)];}
